parts.text:
{
  "units": [
    {
      "quote": "29 CFR 825.110 — Eligible employee.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Regulatory section heading specifying the topic as eligible employee under 29 CFR 825.110, containing no independent substantive requirement or standard."
    },
    {
      "quote": "Has been employed by the employer for at least 12 months",
      "scope_quotes": [
        "An eligible employee is an employee of a covered employer who:"
      ],
      "kind": "threshold",
      "meaning": "An employee of a covered employer must have accumulated a minimum threshold of at least 12 months of employment with the employer to be an eligible employee under the FMLA."
    },
    {
      "quote": "Has been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave ( see § 825.801 for special hours of service requirements for airline flight crew employees)",
      "scope_quotes": [
        "An eligible employee is an employee of a covered employer who:"
      ],
      "kind": "threshold",
      "meaning": "An employee of a covered employer must have been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of leave, subject to special hours of service rules in § 825.801 for airline flight crew employees, to qualify as an eligible employee."
    },
    {
      "quote": "Is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite.",
      "scope_quotes": [
        "An eligible employee is an employee of a covered employer who:"
      ],
      "kind": "threshold",
      "meaning": "To be an eligible employee, the employee must be employed at a worksite where 50 or more employees are employed by the employer within a 75-mile radius of that worksite."
    },
    {
      "quote": "See § 825.105(b) regarding employees who work outside the U.S.",
      "scope_quotes": [
        "Is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite."
      ],
      "kind": "background",
      "meaning": "Cross-reference pointing to § 825.105(b) for provisions concerning employees working outside the United States, providing no independent substantive rule here."
    },
    {
      "quote": "The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
      "scope_quotes": [
        "An eligible employee is an employee of a covered employer who:",
        "Has been employed by the employer for at least 12 months"
      ],
      "kind": "permission",
      "meaning": "The 12 months of employment required to establish eligibility are not required to be consecutive months, provided the qualifying conditions regarding breaks in service are satisfied."
    },
    {
      "quote": "Subject to the exceptions provided in paragraph (b)(2) of this section, employment periods prior to a break in service of seven years or more need not be counted in determining whether the employee has been employed by the employer for at least 12 months.",
      "scope_quotes": [
        "The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "exemption",
      "meaning": "Employers are excused from counting employment periods that precede a break in service of seven years or more toward the 12-month employment requirement, unless one of the exceptions in paragraph (b)(2) applies."
    },
    {
      "quote": "The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation.",
      "scope_quotes": [
        "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "exception",
      "meaning": "Employment periods occurring prior to a break in service of more than seven years must be counted toward the 12-month requirement if the break was caused by fulfilling a USERRA-covered service obligation."
    },
    {
      "quote": "The period of absence from work due to or necessitated by USERRA-covered service must be also counted in determining whether the employee has been employed for at least 12 months by the employer.",
      "scope_quotes": [
        "The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation."
      ],
      "kind": "requirement",
      "meaning": "The employer must count any period of absence from work necessitated by or due to USERRA-covered service as time employed when calculating the 12-month employment threshold."
    },
    {
      "quote": "However, this section does not provide any greater entitlement to the employee than would be available under the USERRA; or",
      "scope_quotes": [
        "The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation."
      ],
      "kind": "statement",
      "meaning": "This section does not grant the employee any right or entitlement beyond what is legally available under USERRA."
    },
    {
      "quote": "A written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (e.g., for purposes of the employee furthering his or her education or for childrearing purposes).",
      "scope_quotes": [
        "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "exception",
      "meaning": "Employment periods before a break in service exceeding seven years must be counted toward the 12 months if a written agreement (such as a collective bargaining agreement) establishes the employer's intention to rehire the employee after the break (such as for education or childrearing)."
    },
    {
      "quote": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (sick, vacation) during which other benefits or compensation are provided by the employer (e.g., workers' compensation, group health plan benefits, etc.), the week counts as a week of employment.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "A week qualifies and counts as a full week of employment if the employee is maintained on the employer's payroll for any part of that week, including periods of paid or unpaid leave (such as sick or vacation leave) during which the employer provides other compensation or benefits like workers' compensation or group health plan coverage."
    },
    {
      "quote": "For purposes of determining whether intermittent/occasional/casual employment qualifies as at least 12 months, 52 weeks is deemed to be equal to 12 months.",
      "scope_quotes": [],
      "kind": "threshold",
      "meaning": "When assessing whether intermittent, occasional, or casual employment satisfies the requirement of at least 12 months of employment, 52 weeks is legally treated as equivalent to 12 months."
    },
    {
      "quote": "Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement.",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Employers are permitted, at their discretion, to count employment periods occurring before a continuous break in service of more than seven years toward the 12-month employment requirement."
    },
    {
      "quote": "However, if an employer chooses to recognize such prior employment, the employer must do so uniformly, with respect to all employees with similar breaks in service.",
      "scope_quotes": [
        "Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
      ],
      "kind": "requirement",
      "meaning": "If an employer elects to recognize prior employment before a continuous break of over seven years, the employer is legally obligated to apply that recognition uniformly to all employees who have similar breaks in service."
    },
    {
      "quote": "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The determination of whether an employee has worked the minimum 1,250 hours of service must be made according to FLSA principles for compensable hours of work, except as provided for USERRA-covered service in paragraph (c)(2) and airline flight crew employees in § 825.801."
    },
    {
      "quote": "See 29 CFR part 785.",
      "scope_quotes": [
        "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work."
      ],
      "kind": "background",
      "meaning": "Cross-reference to 29 CFR part 785 regarding FLSA principles of compensable hours of work, without creating an independent substantive standard."
    },
    {
      "quote": "The determining factor is the number of hours an employee has worked for the employer within the meaning of the FLSA.",
      "scope_quotes": [
        "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work."
      ],
      "kind": "definition",
      "meaning": "The controlling factor in the 1,250 hours determination is the actual number of hours worked for the employer as defined under the FLSA."
    },
    {
      "quote": "The determination is not limited by methods of recordkeeping, or by compensation agreements that do not accurately reflect all of the hours an employee has worked for or been in service to the employer.",
      "scope_quotes": [
        "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work."
      ],
      "kind": "prohibition",
      "meaning": "The calculation of hours worked cannot be restricted by an employer's recordkeeping practices or by compensation agreements if they fail to accurately record all hours worked by or in service of the employee."
    },
    {
      "quote": "Any accurate accounting of actual hours worked under FLSA's principles may be used.",
      "scope_quotes": [
        "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work."
      ],
      "kind": "permission",
      "meaning": "Any accurate accounting of actual hours worked conforming to FLSA principles is legally acceptable and may be used to show hours of service."
    },
    {
      "quote": "An employee returning from USERRA-covered service shall be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service in determining the employee's eligibility for FMLA-qualifying leave.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "An employer must credit an employee returning from USERRA-covered service with the hours of service they would have performed had they not been absent due to or necessitated by that service when assessing eligibility for FMLA leave."
    },
    {
      "quote": "Accordingly, a person reemployed following USERRA-covered service has the hours that would have been worked for the employer added to any hours actually worked during the previous 12-month period to meet the hours of service requirement.",
      "scope_quotes": [
        "An employee returning from USERRA-covered service shall be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service in determining the employee's eligibility for FMLA-qualifying leave."
      ],
      "kind": "requirement",
      "meaning": "For an individual reemployed after USERRA service, the hours that would have been worked must be added to hours actually worked during the preceding 12-month period to determine if the 1,250 hours of service threshold is reached."
    },
    {
      "quote": "In order to determine the hours that would have been worked during the period of absence from work due to or necessitated by USERRA-covered service, the employee's pre-service work schedule can generally be used for calculations.",
      "scope_quotes": [
        "An employee returning from USERRA-covered service shall be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service in determining the employee's eligibility for FMLA-qualifying leave."
      ],
      "kind": "recommendation",
      "meaning": "To calculate the hours an employee would have worked during a USERRA absence, relying on the employee's pre-service work schedule is generally an authorized and suitable calculation method."
    },
    {
      "quote": "See § 825.801(c) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Cross-reference directing readers to § 825.801(c) for special rules governing airline flight crew employees, with no operative standard established in this sentence."
    },
    {
      "quote": "In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541), the employer has the burden of showing that the employee has not worked the requisite hours.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If an employer fails to keep an accurate record of hours worked—including for FLSA-exempt executive, administrative, or professional employees under 29 CFR part 541—the employer bears the burden of proving that the employee failed to work the required hours of service."
    },
    {
      "quote": "An employer must be able to clearly demonstrate, for example, that full-time teachers ( see § 825.102 for definition) of an elementary or secondary school system, or institution of higher education, or other educational establishment or institution (who often work outside the classroom or at their homes) did not work 1,250 hours during the previous 12 months in order to claim that the teachers are not eligible for FMLA leave.",
      "scope_quotes": [
        "In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541), the employer has the burden of showing that the employee has not worked the requisite hours."
      ],
      "kind": "requirement",
      "meaning": "Where accurate records are not maintained, an employer is required to clearly demonstrate that full-time teachers of elementary, secondary, or higher education institutions did not work 1,250 hours in the prior 12 months to support claiming they are ineligible for FMLA leave."
    },
    {
      "quote": "See § 825.801(d) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Cross-reference pointing to § 825.801(d) for special burden-of-proof rules regarding airline flight crew employees, containing no substantive standard in itself."
    },
    {
      "quote": "The determination of whether an employee meets the hours of service requirement and has been employed by the employer for a total of at least 12 months must be made as of the date the FMLA leave is to start.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The assessment of whether an employee satisfies the 12-month employment requirement and the 1,250-hour service requirement must be determined as of the specific date the FMLA leave is scheduled to begin."
    },
    {
      "quote": "An employee may be on non-FMLA leave at the time he or she meets the 12-month eligibility requirement, and in that event, any portion of the leave taken for an FMLA-qualifying reason after the employee meets the eligibility requirement would be FMLA leave.",
      "scope_quotes": [],
      "kind": "condition",
      "meaning": "An employee is permitted to be on non-FMLA leave when they satisfy the 12-month requirement, and any portion of leave taken for an FMLA-qualifying reason after reaching eligibility must be treated as FMLA leave."
    },
    {
      "quote": "See § 825.300(b) for rules governing the content of the eligibility notice given to employees.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Cross-reference to § 825.300(b) regarding the required content of employee eligibility notices, containing no substantive operational rule."
    },
    {
      "quote": "Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The determination of whether the 50 employees within 75 miles threshold is met must be evaluated at the specific time the employee gives notice of the need for leave."
    },
    {
      "quote": "Whether the leave is to be taken at one time or on an intermittent or reduced leave schedule basis, once an employee is determined eligible in response to that notice of the need for leave, the employee's eligibility is not affected by any subsequent change in the number of employees employed at or within 75 miles of the employee's worksite, for that specific notice of the need for leave.",
      "scope_quotes": [
        "Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave."
      ],
      "kind": "condition",
      "meaning": "Regardless of whether leave is taken continuously, intermittently, or on a reduced schedule, once eligibility is established based on the employee's notice, it remains unaffected for that leave notice by any subsequent drop or change in employee count within 75 miles."
    },
    {
      "quote": "Similarly, an employer may not terminate employee leave that has already started if the employee count drops below 50.",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An employer is prohibited from terminating an employee's already-started FMLA leave if the number of employees within 75 miles subsequently falls below 50."
    },
    {
      "quote": "For example, if an employer employs 60 employees in August, but expects that the number of employees will drop to 40 in December, the employer must grant FMLA benefits to an otherwise eligible employee who gives notice of the need for leave in August for a period of leave to begin in December.",
      "scope_quotes": [
        "Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave."
      ],
      "kind": "requirement",
      "meaning": "An employer employing 50 or more employees (e.g., 60) when notice is given in August must grant FMLA benefits for leave starting in December, even if employment is anticipated to fall below 50 (e.g., to 40) before the leave begins."
    }
  ]
}
